let browseWheel=0,browseWheelTime=0,browseWheelKind='';
canvas.addEventListener('wheel',e=>{
 const kind=presetBrowser?'preset':moduleBrowser||(engineBrowser?'engine':sequenceBrowser?'sequence':'');
 if(!kind||e.ctrlKey)return;
 e.preventDefault();const now=performance.now();if(kind!==browseWheelKind||now-browseWheelTime>220)browseWheel=0;
 browseWheelKind=kind;browseWheelTime=now;
 const delta=Math.abs(e.deltaY)>=Math.abs(e.deltaX)?e.deltaY:e.deltaX;
 const amount=delta*(e.deltaMode===1?16:e.deltaMode===2?160:1);
 if(Math.sign(amount)!==Math.sign(browseWheel))browseWheel=0;browseWheel+=amount;
 if(Math.abs(browseWheel)<40)return;
 const list=presetBrowser?presetChoices().map((_,i)=>String(i)):moduleBrowser?Object.keys(moduleBrowser==='effect'?effects:lfos):engineBrowser?['fm','saw','tone','sample']:['endless','pattern','arp'];
 const value=presetBrowser?String(presetIndex):moduleBrowser?cfg[mode==='mixer'?'masterfxType':moduleBrowser+'Type']:engineBrowser?cfg.engine:cfg.seq.type;
 const index=clamp(list.indexOf(value)+Math.sign(browseWheel),0,list.length-1);browseWheel=0;
 if(list[index]!==value)changeKnob(presetBrowser?1:0,index/Math.max(1,list.length-1));
},{passive:false});
canvas.addEventListener('pointerleave',()=>{browseWheel=0;browseWheelKind='';});
canvas.addEventListener('click',e=>{
 const r=canvas.getBoundingClientRect(),y=(e.clientY-r.top)*320/r.height;
 if(presetBrowser){const row=Math.floor((y-65)/48);if(row<0||row>=presetChoices().length)return;presetIndex=row;loadPreset();presetBrowser=false;}
 else if(moduleBrowser){const list=Object.keys(moduleBrowser==='effect'?effects:lfos),selected=list.indexOf(cfg[mode==='mixer'?'masterfxType':moduleBrowser+'Type']),start=Math.max(0,Math.min(selected-2,list.length-5)),row=Math.floor((y-16)/55);if(row<0||row>=Math.min(5,list.length))return;selectModule(moduleBrowser,list[start+row]);moduleBrowser=null;}
 else if(engineBrowser){const row=Math.floor((y-30)/60);if(row<0||row>3)return;$('#engine').value=['fm','saw','tone','sample'][row];$('#engine').dispatchEvent(new Event('change'));engineBrowser=false;}
 else if(sequenceBrowser){const row=Math.floor((y-30)/60);if(row<0||row>2)return;setSequenceType(['endless','pattern','arp'][row]);sequenceBrowser=false;}
 else return;configure();updatePage();
});
function draw(){requestAnimationFrame(draw);g.clearRect(0,0,640,320);g.lineWidth=3;
 if(helpHeld){g.fillStyle='#e7e8df';g.beginPath();g.roundRect(25,40,590,210,22);g.fill();g.fillStyle='#151910';g.font='24px monospace';g.fillText(helpText.slice(0,37),45,145);}
 else if(mode==='album'){const a=state.album||{side:0,position:0};g.strokeStyle=a.recording?'#e78045':'#6dc98c';for(const r of [90,72,56,17]){g.beginPath();g.arc(325,145,r,0,Math.PI*2);g.stroke();}g.fillStyle='#e7e8df';g.font='27px monospace';g.fillText(a.side?'B':'A',317,155);g.fillText(time(a.position),35,80);g.font='24px monospace';['REC','PLAY','STOP','SIDE'].forEach((t,i)=>{g.fillStyle=colours[i];g.fillText(t,35+i*155,300);});}
 else if(mode==='input'){g.fillStyle='#72bce5';g.font='45px monospace';g.fillText(cfg.inputSource.toUpperCase(),60,100);g.fillStyle='#e7e8df';g.font='24px monospace';g.fillText('THRESHOLD '+Math.round(cfg.inputThreshold*100)+'%',60,180);g.fillStyle='#e78045';g.fillText('GAIN '+Math.round(cfg.inputGain*100)+'%',60,235);}
 else if(mode==='com'){g.fillStyle='#e7e8df';g.font='30px monospace';g.fillText('USB / CONNECTION',65,105);g.font='24px monospace';['DEVICE','CTRL','DISK','OPT'].forEach((t,i)=>{g.fillStyle=colours[i];g.fillText(t,20+i*160,280);});}
 else if(eraseTape){g.fillStyle='#e78045';g.font='32px monospace';g.fillText('ERASE ALL TAPE?',80,100);g.fillStyle='#e7e8df';g.font='23px monospace';g.fillText('Hold T1 + T2 + T3 + T4',65,180);g.fillText('Tape key cancels',120,230);}
 else if(presetBrowser){g.fillStyle='#72bce5';g.font='25px monospace';g.fillText(['FM','SAW','TONE','SAMPLER'][presetCategory],45,38);presetChoices().forEach((p,i)=>{g.fillStyle=i===presetIndex?'#6dc98c':'#8a8f82';g.fillText((i===presetIndex?'› ':'  ')+p[2].toUpperCase(),45,95+i*48);});}
 else if(mode==='tempo'){g.fillStyle='#72bce5';g.font='94px monospace';g.fillText(cfg.bpm.toFixed(shifted?1:0),65,150);g.fillStyle='#6dc98c';g.font='25px monospace';g.fillText(cfg.clockMode.toUpperCase(),65,205);g.fillStyle='#e78045';g.fillText(cfg.metro?'CLICK '+Math.round(cfg.metroPitch*100):'CLICK OFF',65,260);}
 else if(page==='signal'){g.font='24px monospace';g.fillStyle='#72bce5';g.fillText('SOUND → FX → TAPE',65,95);g.fillStyle='#6dc98c';g.fillText('T1 + T2 + T3 + T4',65,165);g.fillStyle='#e78045';g.fillText('→ EQ → FX → DRIVE → OUT',25,235);}
 else if(page==='envelope'&&shifted&&mode!=='mixer'){g.fillStyle='#72bce5';g.font='42px monospace';g.fillText(cfg.playMode.toUpperCase(),70,130);g.fillStyle='#6dc98c';g.font='26px monospace';g.fillText('PORTAMENTO '+Math.round(cfg.portamento*100)+'%',70,205);}
 else if(moduleBrowser){const list=Object.keys(moduleBrowser==='effect'?effects:lfos),selected=list.indexOf(cfg[mode==='mixer'?'masterfxType':moduleBrowser+'Type']),start=Math.max(0,Math.min(selected-2,list.length-5));g.font='28px monospace';list.slice(start,start+5).forEach((name,i)=>{g.fillStyle=start+i===selected?'#72bce5':'#8a8f82';g.fillText((start+i===selected?'› ':'  ')+name.toUpperCase(),45,48+i*55);});}
 else if(page==='effect'){drawEffect(g,mode==='mixer'?cfg.masterfxType:cfg.effectType,mode==='mixer'?cfg.masterfx:(state.modulated?.effect||cfg.effect),state.peak,performance.now()/1000,mode==='mixer'?cfg.masterfxOn:cfg.effectOn);}

 else if(engineBrowser||sequenceBrowser){const options=engineBrowser?['FM BELL','DETUNED SAW','PURE TONE','SAMPLER']:['ENDLESS','PATTERN','ARPEGGIO'],selected=engineBrowser?['fm','saw','tone','sample'].indexOf(cfg.engine):['endless','pattern','arp'].indexOf(cfg.seq.type);g.font='26px monospace';options.forEach((name,i)=>{g.fillStyle=i===selected?'#72bce5':'#8a8f82';g.fillText((i===selected?'› ':'  ')+name,45,65+i*60);});}
 else if(mode==='tape'){
  const rotation=state.seconds*Math.PI*2;for(const x of [170,470]){g.strokeStyle='#e7e8df';g.beginPath();g.arc(x,100,63,0,Math.PI*2);g.moveTo(x+26,100);g.arc(x,100,26,0,Math.PI*2);g.stroke();for(let j=0;j<3;j++){const a=rotation+j*Math.PI*2/3;g.beginPath();g.moveTo(x+Math.cos(a)*34,100+Math.sin(a)*34);g.lineTo(x+Math.cos(a)*55,100+Math.sin(a)*55);g.stroke();}}
  const start=Math.floor(state.seconds/10)*10,span=10;g.strokeStyle='#6a7061';for(let t=0;t<4;t++){const y=205+t*25;g.beginPath();g.moveTo(20,y);g.lineTo(620,y);g.stroke();for(const take of state.takes[t]){const x=20+(take.start-start)/span*600,w=(take.end-take.start)/span*600;if(x+w<20||x>620)continue;g.fillStyle=t===cfg.track?'#e78045':'#8a8f82';g.fillRect(Math.max(20,x),y-6,Math.max(1,Math.min(620,x+w)-Math.max(20,x)),12);}}g.fillStyle='#72bce5';g.fillRect(20+(state.seconds-start)/span*600,185,2,120);
 }else if(page==='sequence'){
  const {start,count}=sequenceWindow(cfg.seq,cursor),width=560/count;for(let i=start;i<start+count;i++){const x=40+(i-start)*width;g.strokeStyle=i===cursor?'#72bce5':'#5a604f';g.strokeRect(x,50,width-4,230);const step=cfg.seq.steps[i];for(const note of step?.notes||[]){g.fillStyle=i===state.seqStep&&state.seqPlaying?'#e78045':'#6dc98c';g.fillRect(x+3,250-((note-48+48)%48)/48*180,Math.max(3,width-10),7);}}
 }else if(mode==='mixer'){const vals=knobValues();for(let i=0;i<4;i++){g.strokeStyle=colours[i];g.strokeRect(80+i*132,45,42,230);g.fillStyle=colours[i];const h=clamp(vals[i],0,1)*220;g.fillRect(85+i*132,270-h,32,h);}}
 else if(page==='lfo'&&mode!=='mixer'){g.strokeStyle='#6dc98c';g.beginPath();for(let i=0;i<560;i++){const x=40+i,y=160-70*lfoWave(i/280,cfg.lfoShape);if(i)g.lineTo(x,y);else g.moveTo(x,y);}g.stroke();g.fillStyle=cfg.lfoOn?'#e78045':'#5a604f';g.beginPath();g.arc(320+(state.modulation||0)*200,265,12,0,Math.PI*2);g.fill();}
 else if(page==='envelope'){g.strokeStyle='#6dc98c';const x1=80+cfg.adsr[0]*70,x2=x1+70+cfg.adsr[1]*40,y=240-cfg.adsr[2]*170;g.beginPath();g.moveTo(35,270);g.lineTo(x1,50);g.lineTo(x2,y);g.lineTo(450,y);g.lineTo(600,270);g.stroke();}
 else if(cfg.engine==='sample'&&page==='engine'){g.strokeStyle='#9fa699';g.beginPath();for(let i=0;i<560;i++){const at=Math.floor(i/560*(sampleData?.length||0)),y=160-(sampleData?.[at]||0)*135;if(i)g.lineTo(40+i,y);else g.moveTo(40+i,y);}g.stroke();for(let i=0;i<4;i++){const x=40+cfg.knobs[i]*560;g.strokeStyle=colours[i];g.beginPath();g.moveTo(x,45+i*8);g.lineTo(x,270);g.stroke();g.fillStyle=colours[i];g.beginPath();g.arc(x,45+i*8,6,0,Math.PI*2);g.fill();}}
 else{if(analyser)analyser.getFloatTimeDomainData(wave);g.strokeStyle=mode==='drum'?'#e78045':page==='effect'?'#e78045':'#72bce5';g.beginPath();let offset=0;for(let i=1;i<512;i++)if(wave[i-1]<=0&&wave[i]>0){offset=i;break;}for(let i=0;i<512;i++){const x=30+i/511*580,y=160-(state.peak>.001?wave[(offset+i)%1024]*250:Math.sin(i/511*Math.PI*6)*55);if(i===0)g.moveTo(x,y);else g.lineTo(x,y);}g.stroke();for(let i=0;i<4;i++){g.fillStyle=colours[i];g.fillRect(35+i*150,280,clamp((cfg.lfoOn&&mode!=='mixer'?state.modulated?.[page==='effect'?'effect':'knobs']?.[i]:undefined)??knobValues()[i],0,1)*110+4,4);}}
}
updatePage();draw();

albumReady=readStudio('album').then(value=>{albumRestore=value;}).catch(()=>{});
soundsReady=readStudio('sounds').then(value=>{if(!value?.banks)return;for(const type of ['synth','drum']){if(value.banks[type]?.length===8){savedBanks[type]=value.banks[type];savedSamples[type]=value.samples[type];banks[type].slots=clone(value.banks[type]);sampleBanks[type]=value.samples[type];}}}).catch(()=>{});

for(const b of $$('.instrument button:not(.key):not(#record):not(#stop):not(#device-shift):not(#octave-down):not(#octave-up):not(.hw-guide)')){
 b.addEventListener('pointerdown',()=>b.click());if(b.classList.contains('preset'))b.addEventListener('keydown',e=>{if(!e.repeat&&['Enter','Space'].includes(e.code))b.click();});
 b.addEventListener('click',e=>{if(e.isTrusted&&e.detail>0){e.preventDefault();e.stopImmediatePropagation();}},true);
}
